{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL injection vulnerability",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4",
      "explanation": "The searchKey parameter is concatenated directly into a SOQL query string without any sanitization or binding. This allows an attacker to inject malicious SOQL syntax and potentially access unauthorized data or perform destructive operations.",
      "remediation": "Replace the dynamic concatenation with a bind variable by changing the query to 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50' and remove the AccessLevel.USER_MODE parameter since it's not needed for this type of query."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOSL Injection in InvoiceSearchController",
      "severity": "High",
      "file": "InvoiceSearchController.cls",
      "lines": "4",
      "explanation": "The input parameter 'invoiceNum' is directly concatenated into a SOSL search term without any sanitization or binding. This creates a potential SOSL injection vulnerability where malicious input could alter the query's behavior.",
      "remediation": "Use bind variables in the SOSL query by replacing the concatenation with a properly bound variable: 'FIND :searchTerm IN ALL FIELDS RETURNING Invoice__c(Id, Name, Amount__c, Status__c)' where searchTerm is set to 'Invoice-' + invoiceNum."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection in ReportFilterController",
      "severity": "High",
      "file": "ReportFilterController.cls",
      "lines": "getFilteredOpportunities method",
      "explanation": "The method constructs a SOQL WHERE clause by directly concatenating user-provided filter strings without any validation or escaping. This allows an attacker to inject malicious SOQL syntax and potentially access unauthorized data or perform destructive operations.",
      "remediation": "Validate field names against an allow-list and use bind variables for values. Replace direct string concatenation with proper SOQL binding or escape user input before inclusion in the query."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS violation on Opportunity.Amount field",
      "severity": "Medium",
      "file": "Opportunity_Stage_Editor.permissionset-meta.xml",
      "lines": "fieldPermissions for Opportunity.Amount",
      "explanation": "The permission set grants read access to Opportunity.Amount but not edit access. However, the Apex code attempts to update the StageName field which is editable, but the query returns the Amount field which is readable only. This could lead to a FLS violation if the code were to attempt to modify or return the Amount field in a future version.",
      "remediation": "Ensure that all fields accessed in queries and DML operations have appropriate CRUD/FLS permissions. If the Amount field is not needed for the operation, remove it from the query. Otherwise, grant edit access to the Amount field in the permission set."
    },
    {
      "category": "C3",
      "title": "Missing sharing enforcement on OpportunityStageService",
      "severity": "Medium",
      "file": "OpportunityStageService.cls",
      "lines": "class declaration",
      "explanation": "The class is declared with 'with sharing' which is good, but the method is @AuraEnabled and can be called externally. The class should enforce proper sharing rules when accessed through external entry points.",
      "remediation": "Ensure that all classes reachable via @AuraEnabled methods are properly enforcing sharing rules. Since this class is already declared with 'with sharing', it's correctly enforcing sharing for internal calls, but verify that the external access pattern doesn't bypass these protections."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violation in ContractAmendmentService",
      "severity": "High",
      "file": "ContractAmendmentService.cls",
      "lines": "getContractsForAmendment method",
      "explanation": "The getContractsForAmendment method performs a SOQL query without enforcing CRUD/FLS. Although Security.stripInaccessible is called afterward, the initial query does not use WITH USER_MODE or explicit CRUD checks, potentially exposing records the user should not be able to read.",
      "remediation": "Add WITH USER_MODE to the SOQL query in getContractsForAmendment method to enforce CRUD/FLS. Also ensure that the update operation in amendContract enforces proper field-level security."
    },
    {
      "category": "C4",
      "title": "Excessive permissions in Contract Amendment Editor permission set",
      "severity": "Medium",
      "file": "Contract_Amendment_Editor.permissionset-meta.xml",
      "lines": "objectPermissions for Contract",
      "explanation": "The permission set grants Edit access to Contract records but does not grant Create or Delete access, which is good. However, it lacks explicit field-level permissions for Legal_Notes__c, which should be restricted as per the description. The lack of field-level security enforcement in the code means that even if the permission set restricts fields, the code doesn't enforce it.",
      "remediation": "Ensure that the permission set explicitly defines field-level access for Legal_Notes__c to be restricted to legal team only. Additionally, modify the Apex code to enforce field-level security using Security.stripInaccessible or similar mechanisms."
    }
  ]
}

